  function transferLocalResource(id,all=true){const have=localResource(id);if(have<=0)return;if(id==='wood')return transferAllLocalWood();const wanted=all?have:1,accepted=C.addResource(id,wanted,'Transfert Cabane du Bûcheron → Entrepôt communal');if(accepted>0){S.localStock[id]=Math.max(0,have-accepted);C.log(`📦 ${accepted} ${C.content.resources.find(r=>r.id===id)?.name||id} transféré(s) de la cabane vers l’Entrepôt communal.`);}if(accepted<wanted)C.log(`🛖 ${wanted-accepted} unité(s) restent à la cabane : l’Entrepôt communal manque de place.`);C.save();render();}
