  function discardLocalResource(id,all=false){if(id==='wood')return;const have=localResource(id);if(have<=0)return;const qty=all?have:1,name=C.content.resources.find(r=>r.id===id)?.name||id;if(all&&!confirm(`Écarter tout le stock local de ${name} (${qty}) ?`))return;S.localStock[id]=Math.max(0,have-qty);C.log(`🗑️ ${qty} ${name} écarté(s) du stock local du Bûcheron.`);C.save();render();}
