  function mastery(){return C.masteryLevel('lumberjack');}function toolMastery(id){if(Array.isArray(S.ownedTools)&&!S.ownedTools.includes(id))return 0;return Math.min(10,1+Math.floor(Number(S.toolXp[id]||0)/24));}function gainTool(id,xp){if(id)S.toolXp[id]=(S.toolXp[id]||0)+Math.max(0,xp||0);}function knowledgeLevel(id){const xp=Number(S.knowledge[id]||0);let lvl=0;for(let i=0;i<K_LEVELS.length;i++)if(xp>=K_LEVELS[i])lvl=i;return lvl;}function gainKnowledge(id,xp){S.knowledge[id]=(S.knowledge[id]||0)+Math.max(0,xp||0);}
  function ownsTool(id){return S.ownedTools.includes(id);}function ownsGear(id){return S.ownedGear.includes(id);}function toolMax(id){return Number(C.lumberTool(id)?.maxDurability||100);}function toolCondition(id){if(typeof S.toolCondition[id]!=='number')S.toolCondition[id]=toolMax(id);return clamp(S.toolCondition[id],0,toolMax(id));}function toolConditionPct(id){return toolMax(id)?toolCondition(id)/toolMax(id)*100:100;}function conditionFactor(id){const p=toolConditionPct(id);return p<=0?0:p<30?.82:p<60?.92:1;}function conditionQualityPenalty(id){const p=toolConditionPct(id);return p<15?-5:p<30?-3:p<60?-1:0;}function conditionDefectPenalty(id){const p=toolConditionPct(id);return p<15?10:p<30?6:p<60?2:0;}function conditionLabel(id){const p=toolConditionPct(id);return p<=0?'Hors service':p<30?'Très usé':p<60?'Émoussé':p<85?'Bon état':'Excellent';}
  function equippedGear(slot){return C.lumberGear(S.equippedGear[slot]);}function gearEffect(key){let n=0;for(const slot of ['rigging','belt','hauling'])n+=Number(equippedGear(slot)?.effects?.[key]||0);return n;}function yardCapacity(){return Math.max(2,Math.round(gearEffect('yardCapacity')||3));}
  function specDefs(){return C.content.lumberSpecializations||[];}function specDef(id){return C.lumberSpecialization(id);}function specPointTotal(){return Math.max(0,Math.floor((S.level-3)/2));}function hasTalent(id){return !!S.specialization.talents[id];}function spentInSpec(id){const d=specDef(id);return d?(d.talents||[]).filter(t=>hasTalent(t.id)).reduce((a,t)=>a+Number(t.cost||1),0):0;}function specPointsSpent(){return specDefs().reduce((a,d)=>a+spentInSpec(d.id),0);}function specPointsFree(){return Math.max(0,specPointTotal()-specPointsSpent());}function activeSpec(id){return S.specialization.primary===id||S.specialization.secondary===id;}function specEffect(key){let n=0;for(const d of specDefs()){if(!activeSpec(d.id))continue;for(const t of d.talents||[])if(hasTalent(t.id))n+=Number(t.effects?.[key]||0);}return n;}function canInvestTalent(specId,t){if(!activeSpec(specId)||hasTalent(t.id)||specPointsFree()<Number(t.cost||1))return false;return (t.requires||[]).every(hasTalent);}function sustainability(zoneId){const d=clamp(S.forest[zoneId]||0),h=clamp(S.forestHealth[zoneId]||0),p=clamp(S.forestPressure[zoneId]||0);return clamp((d+h+(100-p))/3);}function sustainableFactor(zoneId){return clamp((sustainability(zoneId)-55)/45,0,1);}
  function reputationTiers(){return (C.content.lumberReputationTiers||[]).filter(x=>!x.jobId||x.jobId==='lumberjack').sort((a,b)=>Number(a.minReputation||0)-Number(b.minReputation||0));}function reputationTier(){const rep=Number(S.reputation||0);return reputationTiers().filter(t=>rep>=Number(t.minReputation||0)).pop()||reputationTiers()[0]||null;}function nextReputationTier(){const rep=Number(S.reputation||0);return reputationTiers().find(t=>rep<Number(t.minReputation||0))||null;}function sealDefs(){return (C.content.lumberMasterySeals||[]).filter(x=>!x.jobId||x.jobId==='lumberjack');}function masterCareer(){return C.lumberMasterCareer?C.lumberMasterCareer('lumberjack'):(C.content.lumberMasterCareers||[]).find(x=>x.jobId==='lumberjack');}function sealUnlocked(id){return S.masterySeals.includes(id);}function reputationEffect(key){return Number(reputationTier()?.effects?.[key]||0);}function sealEffect(key){return sealDefs().filter(x=>sealUnlocked(x.id)).reduce((a,x)=>a+Number(x.effects?.[key]||0),0);}function masterEffect(key){return S.masterCertified?Number(masterCareer()?.effects?.[key]||0):0;}function careerEffect(key){return reputationEffect(key)+sealEffect(key)+masterEffect(key);}function managedZoneCount(){return C.content.forestZones.filter(z=>zoneAccessible(z)&&sustainability(z.id)>=70).length;}function endorsementThreshold(c){return Number(c?.endorsementTrust??40);}function hasEndorsement(id){return S.endorsements.includes(id);}function canRequestEndorsement(c){return !!c&&!c.masterOnly&&!hasEndorsement(c.id)&&rankOrder()>=4&&S.reputation>=55&&clientTrust(c.id)>=endorsementThreshold(c);}function completedContract(id){return S.contractHistory.some(h=>h.contractId===id&&h.status==='delivered');}function primaryCapstoneDone(){return !!S.specialization.primary&&spentInSpec(S.specialization.primary)>=4;}function activeContractLimit(){return Math.max(3,3+Math.round(careerEffect('activeContractSlots')));}
  function siteDefs(){return C.content.forestSites||[];}function siteDef(id){return C.forestSite(id);}function siteUnlocked(id){return S.unlockedSites.includes(id);}function zoneAccessible(z){return !!z&&meetsGate(z)&&(!z.unique||!z.siteId||siteUnlocked(z.siteId));}function siteRequirements(site){if(!site)return[];const rows=[{label:'Niveau du métier',have:S.level,need:Number(site.minLevel||1)},{label:'Grade professionnel',have:rankOrder(),need:Number(site.minRank||0),displayHave:C.jobRank('lumberjack'),displayNeed:(C.professionalRanks('lumberjack').find(r=>Number(r.order||0)===Number(site.minRank||0))?.name||site.minRank||0)},{label:'Réputation métier',have:S.reputation,need:Number(site.minReputation||0)},{label:'Contrats réussis',have:S.completedContracts,need:Number(site.minContracts||0)},{label:'Arbres remarquables',have:S.stats.rareTrees||0,need:Number(site.minRareTrees||0)}];for(const req of site.requiresSites||[])rows.push({label:`Lieu reconnu : ${siteDef(req)?.name||req}`,have:siteUnlocked(req)?1:0,need:1,boolean:true});return rows.filter(r=>Number(r.need||0)>0||r.boolean).map(r=>({...r,ok:Number(r.have)>=Number(r.need)}));}function siteReady(site){return !!site&&!siteUnlocked(site.id)&&siteRequirements(site).every(r=>r.ok);}
  function wearTool(id,hardness=1,mult=1){const t=C.lumberTool(id);if(!t||!ownsTool(id))return;let wear=Number(t.wear||1.5)*Math.max(1,Number(hardness||1))*Math.max(.35,Number(mult||1));wear*=Math.max(.45,1+gearEffect('wear')+(Number(hardness||1)>=2?specEffect('hardwoodWear')+careerEffect('hardwoodWear'):0));S.toolCondition[id]=clamp(toolCondition(id)-wear,0,toolMax(id));if(S.toolCondition[id]<=0)C.log(`${t.name} est hors service : répare-le dans l’onglet Équipement.`);}
  function repairCost(id){const t=C.lumberTool(id),missing=Math.max(0,toolMax(id)-toolCondition(id));if(!t||missing<=.5)return 0;if(t.starter&&toolCondition(id)<=0)return 0;return Math.max(1,Math.ceil(Number(t.repairBase||5)*(missing/toolMax(id))*Math.max(.55,1-careerEffect('repairDiscount'))));}
  function qualityName(q){q=Number(q||0);return q>=90?'Exceptionnel':q>=78?'Excellent':q>=63?'Sélectionné':q>=40?'Standard':'Endommagé';}
  function marketDemand(id){return clamp(Number(S.marketDemand[id]||1),.5,1.6);}function demandLabel(v){return v>=1.16?'Forte':v<=.88?'Faible':'Normale';}function demandClass(v){return v>=1.16?'high':v<=.88?'low':'normal';}function refreshMarket(force=false){const now=Date.now();if(!force&&now-S.lastMarketTick<180000)return false;for(const m of C.content.lumberMarket||[]){const prev=marketDemand(m.id),pull=(1-prev)*.45,shock=(Math.random()-.5)*.24;S.marketDemand[m.id]=clamp(prev+pull+shock,Number(m.minDemand||.75),Number(m.maxDemand||1.35));}S.lastMarketTick=now;return true;}
  function resourceSalePrice(id){const m=C.lumberMarketItem(id);if(!m)return 0;return Math.max(1,Math.round(Number(m.basePrice||1)*marketDemand(id)*(1+gearEffect('saleTransport'))*(1+careerEffect('marketBonus'))));}
