  function rankOrder(){C.jobRank('lumberjack');return Number(S.rankOrder||0);}function meetsGate(x){return S.level>=Number(x?.level||x?.minLevel||1)&&rankOrder()>=Number(x?.minRank||0);}function clampRep(n){return clamp(Number(n||0),0,100);}function clientTrust(id){return clampRep(S.clientTrust[id]||0);}function clientStatus(v){return v>=70?'Partenaire fidèle':v>=45?'Confiance établie':v>=25?'Habitué':v>=10?'Connaissance':'Nouveau commanditaire';}
  function rankRequirements(rank){const req=rank?.requirements||{},rows=[];const add=(label,have,need)=>rows.push({label,have,need,ok:Number(have)>=Number(need)});add('Niveau du métier',S.level,rank?.minLevel||1);add('Niveau du village',C.state.level,rank?.minVillageLevel||1);for(const key of ['cuts','processed','stocked','replants','puzzlesWon','rareTrees'])if(Number(req[key]||0)>0)add({cuts:'Arbres abattus',processed:'Opérations du bois',stocked:'Bois stocké',replants:'Replantations',puzzlesWon:'Puzzles réussis',rareTrees:'Arbres remarquables'}[key],S.stats[key]||0,req[key]);if(Number(req.contractsCompleted||0)>0)add('Contrats réussis',S.completedContracts,req.contractsCompleted);if(Number(req.reputation||0)>0)add('Réputation métier',S.reputation,req.reputation);if(Number(req.knowledgeCount||0)>0){const count=C.content.trees.filter(t=>knowledgeLevel(t.id)>=Number(req.knowledgeLevel||1)).length;add(`Essences connaissance ≥ ${K_NAMES[Number(req.knowledgeLevel||1)]||req.knowledgeLevel}`,count,req.knowledgeCount);}for(const [toolId,need] of Object.entries(req.toolMastery||{}))add(`Maîtrise ${C.lumberTool(toolId)?.name||toolId}`,toolMastery(toolId),need);return rows;}
  function canPromote(){const next=C.nextProfessionalRank('lumberjack');return !!next&&rankRequirements(next).every(x=>x.ok);}window.lumberPromote=()=>{if(!canPromote())return;const next=C.nextProfessionalRank('lumberjack');C.promoteJob('lumberjack');C.gainVillageXp(8+Number(next?.order||0)*4);C.log(`Promotion professionnelle : le Bûcheron devient ${next.name}.`);C.save();render();triggerWorkshopActionPulse();};
  function contractTemplates(){return (C.content.jobContracts||[]).filter(x=>x.jobId==='lumberjack');}function lumberClients(){return (C.content.jobClients||[]).filter(x=>x.jobId==='lumberjack');}
  function contractEligible(def){if(!def)return false;const client=C.jobClient(def.clientId),siteOk=!def.requiredSite||siteUnlocked(def.requiredSite),masterOk=!def.requiresMaster||S.masterCertified,clientOk=!client||((!client.masterOnly||S.masterCertified)&&rankOrder()>=Number(client.minRank||0));return siteOk&&masterOk&&clientOk&&rankOrder()>=Number(def.minRank||0)&&S.level>=Number(def.minLevel||1)&&S.reputation>=Number(def.minReputation||0)&&clientTrust(def.clientId)>=Number(def.minTrust||0);}
