  function woodCriteriaText(c={}){const bits=[];if(c.treeIds?.length)bits.push(c.treeIds.map(id=>C.tree(id)?.name||id).join(' / '));if(c.qualityMin)bits.push(`Q ≥ ${c.qualityMin}`);if(c.moistureMax<100)bits.push(`humidité ≤ ${c.moistureMax}%`);if(c.straightnessMin)bits.push(`rectitude ≥ ${c.straightnessMin}`);return bits.join(' · ');}
