  function consumeCompatibleWood(qty,c={}){let remaining=Number(qty||0),lots=C.state.materialLots.wood||[];const sorted=[...lots].sort((a,b)=>Number(a.quality||0)-Number(b.quality||0));for(const lot of sorted){if(remaining<=0)break;if(!woodLotMatches(lot,c))continue;const take=Math.min(remaining,Number(lot.quantity||0));lot.quantity-=take;remaining-=take;C.state.resources.wood=Math.max(0,C.resource('wood')-take);}C.state.materialLots.wood=lots.filter(l=>Number(l.quantity||0)>0);if(remaining<=0)C.recordInventoryEvent('out','wood',qty,'Livraison contrat Bûcheron');return remaining<=0;}
  function contractPerformance(def){if(def?.resourceId!=='wood')return {remarkable:false};let remaining=Number(def.quantity||0),q=0,m=0,st=0,n=0;const lots=[...(C.state.materialLots.wood||[])].filter(l=>woodLotMatches(l,def.woodCriteria||{})).sort((a,b)=>Number(a.quality||0)-Number(b.quality||0));for(const lot of lots){if(remaining<=0)break;const take=Math.min(remaining,Number(lot.quantity||0));q+=Number(lot.quality||0)*take;m+=Number(lot.moisture??100)*take;st+=Number(lot.straightness||0)*take;n+=take;remaining-=take;}if(!n)return {remarkable:false};const avg={quality:q/n,moisture:m/n,straightness:st/n},c=def.woodCriteria||{};const remarkable=avg.quality>=Number(c.qualityMin||0)+10&&avg.moisture<=Number(c.moistureMax??100)-6&&avg.straightness>=Number(c.straightnessMin||0)+8;return {remarkable,...avg};}
