  window.lumberAcceptContract=offerId=>{const limit=activeContractLimit();if(S.activeContracts.length>=limit)return alert(`${limit} contrats actifs maximum avec ta renommée actuelle.`);const offer=S.contractOffers.find(x=>x.id===offerId),def=C.jobContract(offer?.contractId);if(!offer||!def||!contractEligible(def))return;S.contractOffers=S.contractOffers.filter(x=>x.id!==offerId);S.activeContracts.push({id:uid(),contractId:def.id,start:Date.now(),end:Date.now()+Number(def.duration||180)*1000});C.log(`Contrat accepté : ${def.name}.`);C.save();render();triggerWorkshopActionPulse();};
