  window.lumberAbandonContract=activeId=>{const active=S.activeContracts.find(x=>x.id===activeId);if(!active)return;if(!confirm('Abandonner ce contrat ? La confiance et la réputation seront pénalisées.'))return;applyContractFailure(active,'contrat abandonné');S.activeContracts=S.activeContracts.filter(x=>x.id!==activeId);C.save();render();};
  function unlockedZones(){return C.content.forestZones.filter(zoneAccessible);}function selectedZone(){return C.forestZone($('#zoneSelect').value);}function selectedTechnique(){return TECH[$('#techniqueSelect').value]||TECH.standard;}function selectedFellTool(){return C.lumberTool($('#fellToolSelect').value);}function bestTool(op){return(C.content.lumberTools||[]).filter(t=>t.operation===op&&meetsGate(t)&&ownsTool(t.id)&&toolCondition(t.id)>0).sort((a,b)=>(Number(b.efficiency||1)*conditionFactor(b.id)+toolMastery(b.id)*.03)-(Number(a.efficiency||1)*conditionFactor(a.id)+toolMastery(a.id)*.03))[0]||null;}
  function rarity(id){return C.forestRarity(id);}function activeRarity(){const r=rarity(S.activeRareId);return r&&S.rareSightings.some(x=>x.rarityId===r.id)?r:null;}function selectedTree(){const r=activeRarity();return C.tree(r?.baseTreeId||$('#treeSelect').value);}
  function ageLabel(v){return v<35?'Jeune':v<68?'Mature':v<84?'Ancienne':'Vénérable';}function pressureLabel(v){return v<25?'Faible':v<55?'Modérée':v<78?'Forte':'Surexploitée';}
  function cleanupSightings(){const now=Date.now();S.rareSightings=S.rareSightings.filter(x=>x.expiresAt>now&&C.forestRarity(x.rarityId));if(S.activeRareId&&!S.rareSightings.some(x=>x.rarityId===S.activeRareId))S.activeRareId='';}
  function regenForest(){const now=Date.now(),mins=Math.max(0,(now-S.lastForestTick)/60000);if(mins<=0)return;for(const z of C.content.forestZones){const pressure=clamp(S.forestPressure[z.id]||0),regenFactor=clamp(1-pressure/130,.25,1);S.forest[z.id]=Math.min(Number(z.maxDensity||100),Number(S.forest[z.id]||0)+Number(z.regenPerMin||0)*regenFactor*mins);S.forestPressure[z.id]=Math.max(0,pressure-Number(z.pressureDecayPerMin||3)*mins);S.forestAge[z.id]=Math.min(100,Number(S.forestAge[z.id]||50)+Number(z.ageGrowthPerMin||.5)*mins);let h=Number(S.forestHealth[z.id]||90);if(S.forest[z.id]<28||S.forestPressure[z.id]>72)h-=.8*mins;else h+=.45*mins;S.forestHealth[z.id]=clamp(h,10,100);}S.lastForestTick=now;cleanupSightings();}
  function rareChance(z,bonus=0){const age=S.forestAge[z.id]||0,health=S.forestHealth[z.id]||0,pressure=S.forestPressure[z.id]||0,base=Number(z.rareChance||4)+bonus+Math.max(0,age-50)*.13+Math.max(0,health-70)*.06-pressure*.08;return clamp(base*(1+specEffect('rareChance')+careerEffect('rareChance')),1,42);}
  function tryFindRare(z,bonus=0){cleanupSightings();const existing=new Set(S.rareSightings.map(x=>x.rarityId)),eligible=(C.content.forestRarities||[]).filter(r=>!existing.has(r.id)&&S.level>=Number(r.minLevel||1)&&rankOrder()>=Number(r.minRank||0)&&(r.zoneIds||[]).includes(z.id)&&(S.forestAge[z.id]||0)>=Number(r.minAge||0));if(!eligible.length||Math.random()*100>=rareChance(z,bonus))return null;const r=eligible[Math.floor(Math.random()*eligible.length)];if(r.legendary&&Math.random()>.16)return null;const s={id:uid(),rarityId:r.id,zoneId:z.id,foundAt:Date.now(),expiresAt:Date.now()+300000};S.rareSightings.push(s);C.log(`${r.legendary?'Découverte légendaire':'Observation forestière'} : ${r.name} repéré dans ${z.name}.`);return s;}
  function renderZonesSelect(){const old=$('#zoneSelect').value;$('#zoneSelect').innerHTML=C.content.forestZones.map(z=>{const access=zoneAccessible(z),gate=meetsGate(z),site=z.siteId?siteDef(z.siteId):null,why=!gate?`niv. ${z.level}, grade ${z.minRank||0}`:z.unique&&!siteUnlocked(z.siteId)?`reconnaître ${site?.name||'le lieu'}`:'';return `<option value="${esc(z.id)}" ${!access?'disabled':''}>${z.icon||'🌲'} ${esc(z.name)}${!access?` — ${esc(why)}`:''}</option>`;}).join('');if(old&&unlockedZones().some(z=>z.id===old))$('#zoneSelect').value=old;else if(unlockedZones()[0])$('#zoneSelect').value=unlockedZones()[0].id;renderTreeSelect();}
  function renderTreeSelect(){const z=selectedZone()||unlockedZones()[0],old=$('#treeSelect').value,trees=(z?.treeIds||[]).map(C.tree).filter(Boolean);$('#treeSelect').innerHTML=trees.map(t=>`<option value="${esc(t.id)}" ${!meetsGate(t)?'disabled':''}>${t.icon||'🌳'} ${esc(t.name)}${!meetsGate(t)?` — niv. ${t.level}, grade ${t.minRank||0}`:''}</option>`).join('');const ar=activeRarity();if(ar&&(ar.zoneIds||[]).includes(z?.id))$('#treeSelect').value=ar.baseTreeId;else if(old&&trees.some(t=>t.id===old&&meetsGate(t)))$('#treeSelect').value=old;renderFellTools();}
