  function cutValues(){const z=selectedZone(),t=selectedTree(),tech=selectedTechnique(),tool=selectedFellTool(),r=activeRarity();if(!z||!t||!tool||!ownsTool(tool.id)||toolCondition(tool.id)<=0)return null;const tm=toolMastery(tool.id),pressure=clamp(S.forestPressure[z.id]||0),health=clamp(S.forestHealth[z.id]||90),age=clamp(S.forestAge[z.id]||50),hard=Number(t.hardness||1)>=2,sustainQ=specEffect('sustainableQuality')*sustainableFactor(z.id);const eff=Math.max(.45,Number(tool.efficiency||1)*conditionFactor(tool.id));const speed=Math.max(.55,1-gearEffect('speed')-specEffect('cutSpeed')-careerEffect('cutSpeed'));const duration=Math.max(4,Math.round(t.duration*tech.duration*Number(r?.durationMultiplier||1)/eff*(1-Math.min(.26,(mastery()-1)*.02+(tm-1)*.012))*speed));const envQuality=(health-75)*.12-(Math.max(0,pressure-35))*.14+(age-50)*.045;const quality=clamp(Math.round(t.qualityBase+(z.qualityBonus||0)+(r?.qualityBonus||0)+(mastery()-1)*1.6+(tm-1)*1.2+(tool.qualityBonus||0)+tech.quality+envQuality+conditionQualityPenalty(tool.id)+specEffect('quality')+(hard?specEffect('hardwoodQuality')+gearEffect('hardwoodQuality'):0)+(r?specEffect('rareQuality'):0)+sustainQ),15,99);const density=Math.max(1,Number(t.densityCost||4)+tech.density+(r?1:0)+specEffect('densityCost'));const defect=Math.max(2,Number(t.defectRisk||10)+tech.defect+(100-health)*.12+pressure*.08-(mastery()-1)*1.2-(tm-1)*.8+conditionDefectPenalty(tool.id)+gearEffect('defect')+specEffect('defect'));return{z,t,tech,tool,tm,r,duration,quality,density,defect,pressure,health,age};}
  function renderPreview(){const v=cutValues();if(!v){$('#cutPreview').innerHTML='<p class="muted">Aucune hache utilisable. Vérifie l’équipement et son état.</p>';$('#startCutBtn').disabled=true;return;}const density=Math.round(S.forest[v.z.id]||0),capacity=yardCapacity(),can=density>=v.density&&v.health>20&&S.logs.length<capacity,k=knowledgeLevel(v.t.id);$('#cutPreview').innerHTML=`${v.r?`<div class="warning-inline rare-target">${v.r.icon||'⭐'} Arbre remarquable ciblé : <b>${esc(v.r.name)}</b></div>`:''}<div class="preview-grid"><div><span>Durée</span><b>${v.duration}s</b></div><div><span>Qualité de coupe</span><b>${v.quality}/100</b></div><div><span>Risque défaut</span><b>${Math.round(v.defect)}%</b></div><div><span>Densité</span><b>${density}/100</b></div></div><div class="yield-preview"><span>Équipement</span><b>${esc(v.tool.name)} · ${Math.round(toolConditionPct(v.tool.id))}% · chantier ${S.logs.length}/${capacity}</b></div><div class="yield-preview"><span>Peuplement</span><b>${ageLabel(v.age)} · pression ${pressureLabel(v.pressure).toLowerCase()}</b></div><div class="yield-preview"><span>Connaissance</span><b>${K_NAMES[k]} · ${Math.round(S.knowledge[v.t.id]||0)} pts</b></div>${can?'':S.logs.length>=capacity?'<div class="warning-inline">Capacité de débardage atteinte : prépare ou stocke un tronc, ou améliore ton moyen de transport.</div>':'<div class="warning-inline">Zone trop dégradée ou trop peu dense : laisse-la récupérer ou replante.</div>'}`;$('#startCutBtn').disabled=!can||S.tasks.length>=1||!!S.pendingPuzzle||!meetsGate(v.t);}
  const ACTIVE_CUT={open:false,raf:0,last:null,force:0,target:65,tol:8,decay:45,tap:8,hits:0,misses:0,distances:[],session:null,running:false,lock:false};
