  function commitActiveCutGesture(session,performance){regenForest();const z=C.forestZone(session.zoneId),t=C.tree(session.treeId),tool=C.lumberTool(session.toolId);if(!z||!t||!tool)return;if(S.tasks.length||S.pendingPuzzle)return alert('Une autre tâche a commencé entre-temps.');if(S.logs.length>=yardCapacity())return alert('Le chantier est plein. Prépare ou stocke un tronc avant une nouvelle coupe.');if((S.forest[z.id]||0)<session.density)return alert('Cette zone doit se régénérer avant une nouvelle coupe.');S.forest[z.id]=Math.max(0,S.forest[z.id]-session.density);S.forestPressure[z.id]=clamp((S.forestPressure[z.id]||0)+(session.density*1.8+session.pressureDelta)*Math.max(.55,specEffect('pressureMult')||1));S.forestAge[z.id]=clamp((S.forestAge[z.id]||50)-Number(t.ageImpact||2)*(session.rareId?1.25:1));if(S.forestPressure[z.id]>70)S.forestHealth[z.id]=clamp((S.forestHealth[z.id]||90)-2);if(session.rareId){S.rareSightings=S.rareSightings.filter(x=>x.rarityId!==session.rareId);S.activeRareId='';}const duration=Math.max(3,Math.round(Number(session.duration||8)*Number(performance.durationMult||1)));const now=Date.now(),task={id:uid(),kind:'cut',zoneId:z.id,treeId:t.id,rareId:session.rareId,technique:session.technique,toolId:tool.id,start:now,end:now+duration*1000,duration,activeCut:performance};S.tasks.push(task);C.log(`Geste ${performance.grade} : coupe engagée sur ${t.name.toLowerCase()} · abattage ${duration}s · précision ${performance.meanDistance} · ${performance.misses} reprise${performance.misses>1?'s':''}.`);C.save();render();triggerWorkshopActionPulse();}
