  function opDuration(op,lot,tool){let d=Number(op.duration||8);if(op.id==='dry'){const t=C.tree(lot.treeId);d=Math.max(10,Math.round((lot.moisture-18)*.72/Math.max(.35,Number(t?.dryingRate||1))));if(lot.barked)d=Math.round(d*.78);}if(tool)d=d/Math.max(.35,Number(tool.efficiency||1)*conditionFactor(tool.id))*(1-Math.min(.25,(toolMastery(tool.id)-1)*.025));d*=Math.max(.65,1-gearEffect('speed'));return Math.max(3,Math.round(d));}
